    "chapter": "第 2 章：資安標準與控制框架（ISO 27001 與 NIST CSF）",
    "subtopic": "營運衝擊分析 BIA 實務（實務佈建與防禦技術）",
    "question": "於證券期貨業落實「營運衝擊分析 BIA 實務（營運衝擊分析）」之生產環境技術佈建與架構防禦時，針對關鍵控制項「關鍵業務中斷損失量化」之實務做法，下列何者符合最佳工程實踐？",
    "enTerms": [
      {
        "en": "Business Impact Analysis (BIA)",
        "zh": "營運衝擊分析"
      }
    ],
    "options": {
      "A": "評估員工午餐便當菜色對下午工作心情之衝擊。",
      "B": "評估關鍵業務流程遭受中斷時在財務、法遵及商譽之量化損失，據以訂定 RTO、RPO 與最大容忍中斷時間 MTD。",
      "C": "依據各部門辦公室面積大小決定復原優先順序。",
      "D": "宣稱所有系統均無營運衝擊而無需進行任何分析。"
    },
    "answer": "B",
    "analysis": {
      "A": "【錯誤】此項敘述違背了金融資安法令法規與治理標準，在真實金融環境下將直接導致重大合規缺失或被金管會裁罰。",
      "B": "【正確】評估關鍵業務流程遭受中斷時在財務、法遵及商譽之量化損失，據以訂定 RTO、RPO 與最大容忍中斷時間 MTD。在生產環境落實深層防禦必須嚴密依循此技術標準。",
      "C": "【錯誤】此做法破壞了資通安全縱深防禦與密碼學防護機制，在生產環境中將引發災難性之單點安全崩潰。",
      "D": "【錯誤】此選項屬於典型荒謬干擾項，嚴重違反資通安全基本常理，亦無法達成任何安全防護目標。"
    }
